<script setup lang="ts">
import {computed} from 'vue';import {Check,ArrowRight,Sparkles} from '@lucide/vue';
export type Plan={id:string;name:string;description?:string;price:number;features:string[];featured?:boolean;cta?:string;badge?:string;priceNote?:string;excludedFeatures?:string[]};
const p=withDefaults(defineProps<{plans:Plan[];currency?:string;period?:string;modelValue?:string;heading?:string;subtitle?:string;columns?:2|3|4}>(),{currency:'USD',period:'month',columns:3});
const emit=defineEmits<{'update:modelValue':[id:string]}>();const money=(n:number)=>new Intl.NumberFormat(undefined,{style:'currency',currency:p.currency,maximumFractionDigits:n%1===0?0:2}).format(n);
</script><template><section class="vx-pricing"><header v-if="heading||subtitle" class="vx-pricing__heading"><h2 v-if="heading">{{heading}}</h2><p v-if="subtitle">{{subtitle}}</p></header><div class="vx-pricing-grid" :style="{'--vx-price-columns':columns}"><article v-for="plan in plans" :key="plan.id" class="vx-pricing-plan" :class="{'is-featured':plan.featured,'is-selected':modelValue===plan.id}">
<div v-if="plan.featured" class="vx-pricing-plan__ribbon"><Sparkles :size="14"/> {{plan.badge||'Most popular'}}</div><div class="vx-pricing-plan__inner"><div class="vx-pricing-plan__top"><span class="vx-pricing-plan__eyebrow">{{plan.featured?'RECOMMENDED PLAN':'SUBSCRIPTION PLAN'}}</span><h3>{{plan.name}}</h3><p>{{plan.description||'All the essentials to get started.'}}</p></div><div class="vx-pricing-plan__amount"><strong>{{money(plan.price)}}</strong><span>/{{period}}</span></div><p class="vx-pricing-plan__note">{{plan.priceNote||'Billed '+(period==='month'?'monthly':'per '+period)}}</p><button type="button" class="vx-pricing-plan__cta" :class="{'vx-pricing-plan__cta--featured':plan.featured}" @click="emit('update:modelValue',plan.id)">{{modelValue===plan.id?'Selected':(plan.cta||'Choose '+plan.name)}} <ArrowRight :size="17"/></button><div class="vx-pricing-plan__rule"></div><h4>What's included</h4><ul><li v-for="feature in plan.features" :key="feature"><Check :size="17"/> <span>{{feature}}</span></li></ul></div></article></div></section></template>